import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.ClgMjOt7.js";const m=JSON.parse('{"title":"テレメトリ & クラッシュハンドラー仕様","description":"GlitchTip の動的切り替えと CrashHandler 実装","frontmatter":{"title":"テレメトリ & クラッシュハンドラー仕様","description":"GlitchTip の動的切り替えと CrashHandler 実装"},"headers":[],"relativePath":"dev/telemetry-spec.md","filePath":"dev/telemetry-spec.md","lastUpdated":1789107345000}'),l={name:"dev/telemetry-spec.md"};function d(o,e,n,r,c,p){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="テレメトリ-クラッシュハンドラー仕様" tabindex="-1">テレメトリ &amp; クラッシュハンドラー仕様 <a class="header-anchor" href="#テレメトリ-クラッシュハンドラー仕様" aria-label="Permalink to &quot;テレメトリ &amp; クラッシュハンドラー仕様&quot;">​</a></h1><hr><h2 id="sdk-動的制御-illustiaapplication" tabindex="-1">SDK 動的制御 (<code>IllustiaApplication</code>) <a class="header-anchor" href="#sdk-動的制御-illustiaapplication" aria-label="Permalink to &quot;SDK 動的制御 (`IllustiaApplication`)&quot;">​</a></h2><p><code>AppSettings.sendTelemetry</code>（デフォルト <code>false</code>）の値に基づき、GlitchTip 互換の Sentry Android SDK を動的に開始・停止します。</p><p>SDK の ContentProvider による自動初期化は <code>AndroidManifest.xml</code> の <code>io.sentry.auto-init=false</code> で無効化されています。ユーザーが明示的にオプトインした場合に限り <code>GlitchTipTelemetry</code> が SDK を初期化し、オプトアウト時は直ちに停止します。</p><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GlitchTipTelemetry.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setEnabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(applicationContext, settings.sendTelemetry)</span></span></code></pre></div><p>GlitchTip の DSN は <code>AndroidManifest.xml</code> に設定し、パフォーマンストレースは 1% をサンプリングします。GlitchTip が非対応の自動セッション追跡、既定 PII、ネットワークイベントおよびユーザー操作の breadcrumb は無効です。</p><hr><h2 id="ローカルクラッシュハンドラー-crashhandler" tabindex="-1">ローカルクラッシュハンドラー (<code>CrashHandler</code>) <a class="header-anchor" href="#ローカルクラッシュハンドラー-crashhandler" aria-label="Permalink to &quot;ローカルクラッシュハンドラー (`CrashHandler`)&quot;">​</a></h2><p><code>Thread.UncaughtExceptionHandler</code> を継承し、未捕獲例外発生時にスタックトレースを解析。リソース未検出 (<code>Resources.NotFoundException</code>) やドキュメントアクセス権限エラーを検知してユーザーに復旧ダイアログをトースト表示。</p>',10)])])}const u=a(l,[["render",d]]);export{m as __pageData,u as default};
